78	vec3 renderSun(in vec3 dir, in vec3 accentColor) {
79	  float alignment = clamp(dot(dir, sundir), 0.0, 1.0);
80	  float core = pow(alignment, 900.0);
81	  float innerCorona = pow(alignment, 140.0);
82	  float outerCorona = pow(alignment, 26.0);
83	  float atmosphericScatter = pow(alignment, 5.5);
84	
85	  vec3 warmCore = vec3(1.0, 0.98, 0.94) * core * 8.5;
86	  vec3 hotCorona = mix(vec3(1.0, 0.94, 0.82), accentColor, 0.18) * innerCorona * 2.6;
87	  vec3 wideHalo = mix(accentColor, vec3(0.84, 0.9, 1.0), 0.34) * outerCorona * 0.72;
88	  vec3 airGlow = mix(accentColor, vec3(0.96, 0.86, 0.7), 0.42) * atmosphericScatter * 0.18;
89	
90	  return warmCore + hotCorona + wideHalo + airGlow;
