93	vec4 integrate(in vec4 sum, in float diffuse, in float density, in vec3 backgroundColor, in float travel) {
94	  float densityContrast = smoothstep(0.08, 0.92, density);
95	  vec3 lighting = vec3(0.58, 0.64, 0.74) * 1.08 + 0.72 * vec3(0.82, 0.88, 0.98) * diffuse;
96	  vec4 color = vec4(
97	    mix(vec3(1.18, 1.2, 1.24), vec3(0.46, 0.5, 0.58), densityContrast),
98	    densityContrast
99	  );
100	  color.xyz *= lighting;
101	  color.xyz = mix(color.xyz, backgroundColor, 1.0 - exp(-0.0025 * travel * travel));
102	  color.a *= 0.52;
103	  color.rgb *= color.a;
104	  return sum + color * (1.0 - sum.a);
105	}
