107	#define MARCH(STEPS, MAPLOD) for (int index = 0; index < STEPS; index += 1) { vec3 pos = rayOrigin + travel * rayDirection; if (pos.y < -3.0 || pos.y > 1.2 || sum.a > 0.99) break; float density = MAPLOD(pos); if (density > 0.1) { float diffuse = clamp((density - MAPLOD(pos + 0.5 * sundir)) * 2.0, 0.0, 1.0); sum = integrate(sum, diffuse, density, backgroundColor, travel); } travel += max(0.16, 0.022 * travel); }
