109	vec4 raymarch(
110	  in vec3 rayOrigin,
111	  in vec3 rayDirection,
112	  in vec3 backgroundColor,
113	  in float jitter
114	) {
115	  vec4 sum = vec4(0.0);
116	  float travel = 0.18 * jitter;
117	
118	  MARCH(25, map4);
119	  MARCH(20, map3);
120	  MARCH(15, map2);
121	  MARCH(15, map2);
122	
123	  return clamp(sum, 0.0, 1.0);
124	}
