126	mat3 setCamera(in vec3 forward) {
127	  vec3 cw = normalize(forward);
128	  vec3 cu = vec3(-cw.z, 0.0, cw.x);
129	  vec3 cv = normalize(cross(cu, cw));
130	  return mat3(cu, cv, cw);
