133	vec2 applyPointerDistortion(vec2 uv, vec2 safeResolution) {
134	  vec2 pointer = vec2(uPointer.x, 1.0 - uPointer.y);
135	  vec2 delta = uv - pointer;
136	  float distance = length(delta);
137	  float ripple = (1.0 - smoothstep(0.0, 0.26, distance)) * uPointerStrength;
138	  float flowNoise = texture2D(uNoiseTexture, uv * 1.6 + uTime * 0.02).r - 0.5;
139	  vec2 swirl = vec2(-delta.y, delta.x) * ripple * 0.22;
140	  vec2 drift = uPointerVelocity * safeResolution * 0.012 * ripple;
141	  vec2 pulse = delta * flowNoise * ripple * 0.28;
142	  return uv + swirl + drift - pulse;
143	}
