145	vec3 cloudRender(in vec3 rayOrigin, in vec3 rayDirection) {
146	  vec3 heroTopColor = vec3(0.005, 0.012, 0.05);
147	  vec3 heroBottomColor = vec3(0.02, 0.09, 0.34);
148	  vec3 heroAccentColor = vec3(0.08, 0.24, 0.62);
149	  float verticalMix = smoothstep(-0.45, 0.95, rayDirection.y * 1.12);
150	  vec3 skyBase = mix(heroBottomColor, heroTopColor, verticalMix);
151	  vec3 deepSky = mix(skyBase, heroAccentColor, 0.1);
152	  float sunAlignment = clamp(dot(rayDirection, sundir), 0.0, 1.0);
153	  vec3 color = deepSky * mix(0.42, 0.82, clamp(rayDirection.y * 0.5 + 0.5, 0.0, 1.0));
154	  color -= rayDirection.y * 0.18 * deepSky;
155	  color += mix(heroAccentColor, vec3(0.9, 0.93, 1.0), 0.18) * pow(sunAlignment, 7.0) * 0.07;
156	  color += renderSun(rayDirection, heroAccentColor);
157	
158	  float jitter = hash12(gl_FragCoord.xy);
159	  vec4 clouds = raymarch(rayOrigin, rayDirection, color, jitter);
160	  color = color * (1.0 - clouds.w) + clouds.xyz;
161	  color *= 0.78;
162	  color *= mix(1.0, 0.42, clamp(uHeroDarken, 0.0, 1.0));
163	  return color;
164	}
