166	void main() {
167	  vec2 safeResolution = max(uResolution, vec2(1.0));
168	  vec2 q = gl_FragCoord.xy / safeResolution;
169	  q = mix(q, applyPointerDistortion(q, safeResolution), clamp(uPointerActive + uPointerStrength, 0.0, 1.0));
170	  vec2 p = -1.0 + 2.0 * q;
171	  p.x *= safeResolution.x / safeResolution.y;
172	
173	  speed = uTime * SPEED;
174	  vec3 rayOrigin = 4.0 * normalize(vec3(0.0, 0.3, 5.0));
175	  vec3 target = vec3(0.0, -1.0, 0.0);
176	  mat3 camera = setCamera(target - rayOrigin);
177	  vec3 rayDirection = camera * normalize(vec3(p.xy, 1.0));
178	  vec3 color = cloudRender(rayOrigin, rayDirection);
179	
180	  gl_FragColor = vec4(color, 1.0);
181	}
