8	const INTRO_DOM_SELECTORS = [
9	  DOM_CONFIG.keys.intro?.title,
10	  DOM_CONFIG.keys.intro?.desc,
11	  DOM_CONFIG.keys.intro?.time,
12	  DOM_CONFIG.keys.intro?.btn,
13	  DOM_CONFIG.keys.intro?.section,
14	].filter((selector): selector is string => typeof selector === "string" && selector.length > 0);
15	const DOM_WAIT_TIMEOUT_MS = 4000;
16	
17	export class IntroOverlay {
18	  constructor(private readonly _config: IntroConfig) {}
19	
20	  async run(params: {
21	    gsap: GsapGlobal;
22	    loadPromise: Promise<unknown>;
23	    onComplete?: () => void | Promise<void>;
24	  }): Promise<void> {
25	    let releaseScrollLock: (() => void) | null = null;
26	    if (this._config.waitForDomSelectors !== false) {
27	      const selectorsReady = await IntroOverlay.waitForDomSelectors(
28	        INTRO_DOM_SELECTORS,
29	        DOM_WAIT_TIMEOUT_MS,
30	      );
31	      if (!selectorsReady) {
32	      }
33	    }
34	
35	    IntroOverlay.show();
36	    const rawTl = params.gsap.timeline({ paused: true });
37	    const controller = new TimelineController(rawTl);
38	
39	    rawTl.eventCallback?.("onStart", () => {
40	      IntroOverlay.show();
41	      releaseScrollLock?.();
42	      releaseScrollLock = ScrollLock.lock();
43	      window.scrollTo({ top: 0, behavior: "auto" });
44	    });
45	
46	    rawTl.progress(0);
47	    this._config.tl(rawTl, {
48	      controller,
49	      loadPromise: params.loadPromise.then(() => undefined),
50	      gsap: params.gsap,
51	    });
52	
53	    await new Promise<void>((resolve) => {
54	      rawTl.eventCallback?.("onComplete", () => {
55	        IntroOverlay.hide();
56	        releaseScrollLock?.();
57	        releaseScrollLock = null;
58	        window.scrollTo({ top: 0, behavior: "auto" });
59	        void (async () => {
60	          try {
61	            await params.onComplete?.();
62	          } finally {
63	            resolve();
64	          }
65	        })();
66	      });
67	      controller.play();
68	    });
69	
70	    controller.dispose();
71	    if (releaseScrollLock !== null) {
72	      const runRelease: () => void = releaseScrollLock;
73	      runRelease();
74	    }
75	  }
76	
77	  dispose(): void {}
78	
79	  static show(): void {
80	    document.documentElement.classList.add("is-intro");
81	    IntroCanvas.ensure();
82	    IntroOverlay._setVisibilityState(true);
83	  }
84	
85	  static hide(): void {
86	    document.documentElement.classList.remove("is-intro");
87	    IntroOverlay._setVisibilityState(false);
88	  }
